CREATE OR REPLACE FUNCTION public.gridex_assign_customer_contract_identity_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.customer_id is null or new.company_id is null then return new; end if;
  if nullif(btrim(new.customer_number),'') is null then
    select c.customer_number into new.customer_number from public.customers c where c.id=new.customer_id and c.company_id=new.company_id;
  end if;
  if nullif(btrim(new.customer_number),'') is null then raise exception using errcode='23502',message='customer_contract_customer_number_required'; end if;
  if nullif(btrim(new.contract_number),'') is null then new.contract_number := public.gridex_next_contract_number(new.company_id,new.customer_number); end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_fill_customer_contract_price_area_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_site_area text; v_meter_area text; v_site_grid text; v_meter_grid text; v_area text; v_grid text;
begin
  if new.customer_site_id is not null or new.site_id is not null then
    select upper(nullif(btrim(s.price_area_code),'')), upper(nullif(btrim(s.grid_area_code),'')) into v_site_area,v_site_grid
    from public.customer_sites s where s.id=coalesce(new.customer_site_id,new.site_id) and s.company_id=new.company_id limit 1;
  end if;
  if new.metering_point_id is not null then
    select upper(nullif(btrim(coalesce(m.price_area_code,m.price_area)),'')), upper(nullif(btrim(m.grid_area_code),'')) into v_meter_area,v_meter_grid
    from public.metering_points m where m.id=new.metering_point_id and m.company_id=new.company_id limit 1;
  end if;
  if v_site_area in ('SE1','SE2','SE3','SE4') and v_meter_area in ('SE1','SE2','SE3','SE4') and v_site_area<>v_meter_area then
    raise exception using errcode='23514',message='contract_price_area_source_conflict';
  end if;
  v_area:=coalesce(case when v_meter_area in ('SE1','SE2','SE3','SE4') then v_meter_area end,case when v_site_area in ('SE1','SE2','SE3','SE4') then v_site_area end);
  v_grid:=coalesce(v_meter_grid,v_site_grid);
  if nullif(btrim(coalesce(new.price_area_used,'')),'') is null then new.price_area_used:=v_area;
  elsif v_area is not null and upper(btrim(new.price_area_used))<>v_area then raise exception using errcode='23514',message='contract_price_area_binding_mismatch';
  else new.price_area_used:=upper(btrim(new.price_area_used)); end if;
  if nullif(btrim(coalesce(new.grid_area_code_used,'')),'') is null then new.grid_area_code_used:=v_grid;
  elsif v_grid is not null and upper(btrim(new.grid_area_code_used))<>v_grid then raise exception using errcode='23514',message='contract_grid_area_binding_mismatch';
  else new.grid_area_code_used:=upper(btrim(new.grid_area_code_used)); end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.gridex_enforce_quote_binding_v2()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_row jsonb:=to_jsonb(new);
  v_quote public.website_contract_quotes%rowtype;
  v_company_id uuid:=nullif(v_row->>'company_id','')::uuid;
  v_quote_reference text:=nullif(v_row->>'quote_reference','');
  v_text text;
begin
  if v_quote_reference is null then return new; end if;

  select * into v_quote
  from public.website_contract_quotes q
  where q.company_id=v_company_id
    and q.quote_reference=v_quote_reference;
  if not found then
    raise exception using errcode='23503',message='quote_binding_not_found_for_tenant';
  end if;

  foreach v_text in array array[
    nullif(v_row->>'contract_product_id',''),
    nullif(v_row->>'contract_product_version_id',''),
    nullif(v_row->>'contract_publication_version_id',''),
    nullif(v_row->>'price_plan_id',''),
    nullif(v_row->>'price_plan_version_id',''),
    nullif(v_row->>'price_book_id',''),
    nullif(v_row->>'legal_bundle_version_id',''),
    nullif(v_row->>'energy_direction','')
  ] loop
    if v_text is null then
      raise exception using errcode='23502',message='quote_binding_target_identity_incomplete';
    end if;
  end loop;

  if v_quote.contract_product_id is distinct from (v_row->>'contract_product_id')::uuid then
    raise exception using errcode='23514',message='quote_binding_contract_product_mismatch';
  end if;
  if v_quote.contract_product_version_id is distinct from (v_row->>'contract_product_version_id')::uuid then
    raise exception using errcode='23514',message='quote_binding_contract_version_mismatch';
  end if;
  if v_quote.contract_publication_version_id is distinct from (v_row->>'contract_publication_version_id')::uuid then
    raise exception using errcode='23514',message='quote_binding_publication_version_mismatch';
  end if;
  if v_quote.price_plan_id is distinct from (v_row->>'price_plan_id')::uuid then
    raise exception using errcode='23514',message='quote_binding_price_plan_mismatch';
  end if;
  if v_quote.price_plan_version_id is distinct from (v_row->>'price_plan_version_id')::uuid then
    raise exception using errcode='23514',message='quote_binding_price_plan_version_mismatch';
  end if;
  if v_quote.price_book_id is distinct from (v_row->>'price_book_id')::uuid then
    raise exception using errcode='23514',message='quote_binding_price_book_mismatch';
  end if;
  if v_quote.legal_bundle_version_id is distinct from (v_row->>'legal_bundle_version_id')::uuid then
    raise exception using errcode='23514',message='quote_binding_legal_bundle_mismatch';
  end if;
  if v_quote.energy_direction is distinct from (v_row->>'energy_direction') then
    raise exception using errcode='23514',message='quote_binding_energy_direction_mismatch';
  end if;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_bind_customer_contract_to_exact_publication()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v public.contract_publication_versions;
  pv public.contract_product_versions;
begin
  if new.contract_publication_version_id is not null then
    select cpv.*
    into v
    from public.contract_publication_versions cpv
    join public.contract_publications publication
      on publication.id = cpv.contract_publication_id
    join public.tenant_contract_assignments assignment
      on assignment.id = publication.assignment_id
    where cpv.id = new.contract_publication_version_id
      and assignment.company_id = new.company_id
      and assignment.status = 'active'
      and cpv.status = 'published'
      and cpv.locked_at is not null
      and (new.offer_reference is null or new.offer_reference = cpv.offer_reference)
    limit 1;
  elsif new.public_contract_offer_id is not null or new.offer_reference is not null then
    select cpv.*
    into v
    from public.contract_publication_versions cpv
    where cpv.offer_reference = new.offer_reference
      and cpv.legacy_public_contract_offer_id = new.public_contract_offer_id
      and cpv.status = 'published'
      and cpv.locked_at is not null
      and exists (
        select 1
        from public.public_contract_offers offer
        where offer.id = cpv.legacy_public_contract_offer_id
          and offer.company_id = new.company_id
      )
    limit 1;
  else
    return new;
  end if;

  if not found then
    raise exception using errcode='23514', message='exact_published_contract_version_required';
  end if;

  select *
  into pv
  from public.contract_product_versions
  where id = v.contract_product_version_id
    and locked_at is not null
    and status = 'approved';
  if not found then
    raise exception using errcode='23514', message='exact_approved_contract_product_version_required';
  end if;

  new.offer_reference := v.offer_reference;
  new.contract_publication_version_id := v.id;
  new.contract_product_version_id := pv.id;
  new.contract_product_id := pv.contract_product_id;
  new.legal_bundle_version_id := v.legal_bundle_version_id;
  new.price_plan_id := v.price_plan_id;
  new.price_plan_version_id := v.price_plan_version_id;
  new.price_book_id := v.price_book_id;
  new.commercial_snapshot := coalesce(
    v.publication_snapshot->'commercial_snapshot',
    pv.commercial_snapshot,
    '{}'::jsonb
  );
  new.legal_snapshot := coalesce(
    v.publication_snapshot->'legal_snapshot',
    (select rendered_snapshot from public.legal_bundle_versions where id = v.legal_bundle_version_id),
    '{}'::jsonb
  );
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_bind_internal_customer_contract()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_publication_id uuid; v_publication public.contract_publication_versions%rowtype;
  v_product public.contract_product_versions%rowtype;
begin
  if new.contract_offer_id is null or new.contract_publication_version_id is not null then return new; end if;
  v_publication_id:=public.gridex_ensure_internal_contract_publication(new.company_id,new.contract_offer_id,coalesce(new.created_by,new.updated_by));
  select * into v_publication from public.contract_publication_versions where id=v_publication_id;
  select * into v_product from public.contract_product_versions where id=v_publication.contract_product_version_id;
  new.contract_publication_version_id:=v_publication.id;
  new.contract_product_version_id:=v_product.id;
  new.contract_product_id:=v_product.contract_product_id;
  new.legal_bundle_version_id:=v_publication.legal_bundle_version_id;
  new.price_plan_id:=v_publication.price_plan_id;
  new.price_plan_version_id:=v_publication.price_plan_version_id;
  new.price_book_id:=v_publication.price_book_id;
  new.offer_reference:=coalesce(new.offer_reference,v_publication.offer_reference);
  new.commercial_snapshot:=v_product.commercial_snapshot;
  new.legal_snapshot:=(select rendered_snapshot from public.legal_bundle_versions where id=v_publication.legal_bundle_version_id);
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.gridex_enforce_contract_availability_and_capacity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  o public.contract_offers%rowtype;
  v_count bigint;
  v_statuses text[]:=array['draft','pending_signature','signed','active'];
  v_reserved_one_off boolean:=false;
begin
  if new.status not in ('draft','pending_signature','signed','active') then
    return new;
  end if;
  if new.contract_offer_id is null and new.contract_product_id is null and new.contract_product_version_id is null then
    return new;
  end if;

  select * into o
  from public.contract_offers
  where company_id=new.company_id and (
    id=new.contract_offer_id
    or (new.contract_product_version_id is not null and contract_product_version_id=new.contract_product_version_id)
    or (new.contract_product_id is not null and contract_product_id=new.contract_product_id and lifecycle_status='published')
  )
  order by version_number desc limit 1 for update;
  if not found then
    raise exception using errcode='23514',message='contract_offer_not_available';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(o.version_series_id::text,0));

  -- A materializer-reserved one-off offer is bindable only by the contract that
  -- references it directly, in the same tenant, and only by one contract.
  if o.id=new.contract_offer_id then
    update gridex_one_off_offer_binding.reservations r
    set consumed_contract_id=new.id,consumed_at=coalesce(r.consumed_at,now())
    where r.offer_id=o.id and r.company_id=new.company_id
      and (r.consumed_contract_id is null or r.consumed_contract_id=new.id)
      and (r.intended_contract_id is null or r.intended_contract_id=new.id);
    v_reserved_one_off:=found;
  end if;

  if not v_reserved_one_off and (
     o.lifecycle_status<>'published' or not o.is_active
     or (o.valid_from is not null and o.valid_from>current_date)
     or (o.valid_to is not null and o.valid_to<current_date)) then
    raise exception using errcode='23514',message='contract_offer_not_available';
  end if;
  if not exists(
    select 1 from public.tenant_contract_assignments ta
    join public.tenant_contract_channels ch on ch.assignment_id=ta.id
    where ta.company_id=new.company_id
      and ta.contract_product_version_id=o.contract_product_version_id
      and ta.status='active'
      and ch.channel in ('internal','website','api','partner','phone') and ch.status='active'
      and (
        (ch.channel='internal' and ta.internal_sales_allowed)
        or (ch.channel='website' and ta.website_publication_allowed)
        or ch.channel in ('api','partner','phone')
      )
      and (ch.valid_from is null or ch.valid_from<=now())
      and (ch.valid_to is null or ch.valid_to>=now())
  ) then
    raise exception using errcode='23514',message='contract_channel_not_available';
  end if;

  if o.max_customers is not null then
    select count(*) into v_count
    from public.customer_contracts c
    where c.company_id=new.company_id and c.id is distinct from new.id
      and c.status=any(v_statuses) and (
        c.contract_offer_id=o.id
        or c.contract_product_id=o.contract_product_id
        or c.contract_product_version_id=o.contract_product_version_id
      );
    if v_count>=o.max_customers then
      raise exception using errcode='23514',message='contract_capacity_reached';
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.gridex_assert_customer_not_archived_for_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_status text;
begin
  if new.customer_id is null then
    return new;
  end if;

  select status into v_status from public.customers where id = new.customer_id;

  if v_status = 'archived' then
    raise exception 'Customer % is archived, new % rows are blocked', new.customer_id, tg_table_name
      using errcode = 'P0001';
  end if;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION gridex_ediel_retention.record_c40a67d5fa7766230451_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public, pg_catalog, pg_temp'
AS $function$
declare
  v_old jsonb := to_jsonb(old);
  v_new jsonb := to_jsonb(new);
  v_immutable_keys text[] := array[
    'company_id','customer_id','contract_name','contract_type',
    'energy_direction','site_id','customer_site_id','metering_point_id',
    'contract_offer_id','public_contract_offer_id','offer_reference',
    'quote_reference','contract_product_id','contract_product_version_id',
    'contract_publication_version_id','price_plan_id',
    'price_plan_version_id','price_book_id','legal_bundle_version_id',
    'contract_price_snapshot_id','commercial_snapshot','legal_snapshot',
    'legal_versions_snapshot','tenant_communication_snapshot',
    'tenant_communication_snapshot_sha256','tenant_legal_party_snapshot',
    'signature_snapshot','signature_snapshot_sha256',
    'price_snapshot','campaign_snapshot','fixed_price_ore_per_kwh',
    'spot_markup_ore_per_kwh','variable_fee_ore_per_kwh',
    'markup_ore_per_kwh','monthly_fee_sek','invoice_fee_sek',
    'discount_value','discount_unit','start_fee_sek','admin_fee_sek',
    'break_fee_sek','vat_rate','green_fee_mode','green_fee_value',
    'binding_months','notice_months','optional_fee_lines','starts_at',
    'expected_start_at','ends_at','auto_renew_enabled',
    'auto_renew_term_months','terms_version','terms_signed_version',
    'signed_version','signed_at','signed_ip_hash','signed_user_agent'
  ];
  v_key text;
BEGIN IF TG_OP='UPDATE' AND public.ediel_is_qualified_customer_record_transition_v1(TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW)) THEN RETURN NEW;END IF;
  if tg_op='DELETE' then
    if old.status in ('signed','active','terminated','cancelled','expired')
       or old.signed_at is not null or old.locked_at is not null then
      raise exception using errcode='55000',message='signed_customer_contract_delete_forbidden';
    end if;
    return old;
  end if;

  if old.status in ('signed','active','terminated','cancelled','expired')
     or old.signed_at is not null or old.locked_at is not null then
    foreach v_key in array v_immutable_keys loop
      if v_new->v_key is distinct from v_old->v_key then
        raise exception using errcode='55000',message='signed_customer_contract_immutable:'||v_key;
      end if;
    end loop;

    if new.snapshot_hash is distinct from old.snapshot_hash then
      if nullif(btrim(new.snapshot_hash),'') is null
         or not exists (
           select 1 from public.contract_price_snapshots p
           where p.id=old.contract_price_snapshot_id
             and p.company_id=old.company_id
             and p.contract_id=old.id
             and p.snapshot_hash=new.snapshot_hash
             and nullif(btrim(p.snapshot_hash),'') is not null
         ) then
        raise exception using errcode='55000',message='signed_customer_contract_price_hash_binding_invalid';
      end if;
    end if;

    if new.document_sha256 is distinct from old.document_sha256 then
      if old.document_sha256 is not null
         or coalesce(new.document_sha256,'') !~ '^[0-9a-f]{64}$'
         or not exists(
           select 1 from public.customer_contract_documents d
           where d.company_id=old.company_id
             and d.customer_contract_id=old.id
             and d.document_type='signed_contract_pdf'
             and d.document_sha256=new.document_sha256
             and d.verified_at is not null
         ) then
        raise exception using errcode='55000',message='signed_customer_contract_document_hash_binding_invalid';
      end if;
    end if;

    new.locked_at:=coalesce(old.locked_at,old.signed_at,now());
  elsif new.signed_at is not null or new.status in ('signed','active') then
    new.locked_at:=coalesce(new.locked_at,new.signed_at,now());
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_lock_customer_contract_tenant_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare v_profile jsonb; v_company jsonb; v_email jsonb; v_snapshot jsonb;
begin
  if tg_op='UPDATE' and (old.signed_at is not null or old.locked_at is not null or old.status in('signed','active','terminated','cancelled','expired'))
     and old.tenant_communication_snapshot<>'{}'::jsonb then
    new.tenant_communication_snapshot:=old.tenant_communication_snapshot;
    new.tenant_communication_snapshot_sha256:=old.tenant_communication_snapshot_sha256;
    new.tenant_legal_party_snapshot:=old.tenant_legal_party_snapshot;
    return new;
  end if;
  if new.company_id is null then return new; end if;
  select to_jsonb(t) into v_profile from public.tenant_legal_profiles t where t.company_id=new.company_id;
  select to_jsonb(c) into v_company from public.companies c where c.id=new.company_id;
  select to_jsonb(e) into v_email from public.company_email_settings e where e.company_id=new.company_id;
  new.tenant_legal_party_snapshot:=jsonb_strip_nulls(jsonb_build_object(
    'company_id',new.company_id,'legal_name',coalesce(v_profile->>'legal_name',v_company->>'name'),
    'organization_number',coalesce(v_profile->>'organization_number',v_company->>'org_number'),
    'postal_address',v_profile->'postal_address','customer_service_email',v_profile->>'customer_service_email',
    'phone',v_profile->>'phone','website',v_profile->>'website','tenant_legal_profile_sha256',encode(digest(coalesce(v_profile,'{}')::text,'sha256'),'hex')
  ));
  v_snapshot:=jsonb_strip_nulls(jsonb_build_object(
    'snapshot_version','gridex_tenant_communication_v1',
    'company_id',new.company_id,'legal_name',coalesce(v_profile->>'legal_name',v_company->>'name'),
    'organization_number',coalesce(v_profile->>'organization_number',v_company->>'org_number'),
    'brand_name',coalesce(v_company#>>'{branding,brand_name}',v_company#>>'{branding,display_name}',v_company->>'name'),
    'sender_name',coalesce(v_email->>'sender_name',v_company#>>'{branding,display_name}',v_company->>'name'),
    'sender_email',v_email->>'sender_email','reply_to',coalesce(v_email->>'reply_to_email',v_email->>'support_email',v_profile->>'customer_service_email'),
    'support_email',coalesce(v_email->>'support_email',v_profile->>'customer_service_email'),
    'logo_url',coalesce(v_company#>>'{branding,logo_url}',v_company->>'logo_url'),
    'brand_colors',coalesce(v_company#>'{branding,colors}','{}'::jsonb),
    'legal_footer',coalesce(v_company#>>'{branding,legal_footer}',v_email->>'legal_footer'),
    'phone',coalesce(v_profile->>'phone',v_company->>'phone'),
    'website',coalesce(v_profile->>'website',v_company->>'website'),
    'contract_publication_version_id',new.contract_publication_version_id,
    'price_plan_version_id',new.price_plan_version_id,'legal_bundle_version_id',new.legal_bundle_version_id,
    'locked_at',coalesce(new.signed_at,new.created_at,now())
  ));
  new.tenant_communication_snapshot:=v_snapshot;
  new.tenant_communication_snapshot_sha256:=encode(digest(v_snapshot::text,'sha256'),'hex');
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.gridex_partner_contract_event_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_event_type text;
  v_data jsonb;
begin
  if coalesce(new.metadata->>'source_channel','') <> 'partner_api' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    v_event_type := 'contract.created';
    v_data := jsonb_build_object(
      'contract_reference',new.customer_contract_reference,
      'status',new.status,
      'offer_reference',new.offer_reference
    );
  elsif new.status is distinct from old.status then
    v_event_type := 'contract.status_changed';
    v_data := jsonb_build_object(
      'contract_reference',new.customer_contract_reference,
      'status',new.status,
      'previous_status',old.status,
      'offer_reference',new.offer_reference
    );
  else
    return new;
  end if;

  perform private.gridex_emit_partner_resource_event_v2(
    new.company_id,
    new.customer_id,
    v_event_type,
    'contract',
    new.customer_contract_reference,
    v_data,
    'partner:' || v_event_type || ':' || new.id::text || ':' || coalesce(new.updated_at::text,new.created_at::text,now()::text)
  );
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_assert_company_operational_for_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
declare
  v_company_status text;
begin
  if new.company_id is null then
    return new;
  end if;

  select status into v_company_status
  from public.companies
  where id = new.company_id;

  if coalesce(v_company_status, 'active') not in ('active', 'onboarding') then
    raise exception 'Tenant % is %, write is blocked for operational data', new.company_id, v_company_status
      using errcode = 'P0001';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION gridex_correction_process.capture_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
 old_row jsonb; new_row jsonb; old_fact jsonb; new_fact jsonb;
 old_company text; new_company text; selected_company uuid; fact_id bigint;
 fields text[]:=ARRAY[
  'id','company_id','customer_id','customer_contract_id','contract_id','site_id','customer_site_id',
  'metering_point_id','meter_point_id','normalized_metering_point_id','facility_id',
  'normalized_facility_id','site_facility_id','ediel_metering_point_id','ediel_reference',
  'grid_owner_id','grid_owner_ediel_id','switch_request_id','supplier_switch_request_id',
  'customer_case_id','customer_operation_job_id','operation_id','outbound_request_id',
  'cancellation_ediel_message_id','source_message_id','source_switch_request_id',
  'outbound_z03_message_id','inbound_z04_message_id','rff_li_reference',
  'event_type','event_status','event_code','case_type','job_type','task_type',
  'request_type','process_type','source_process','source','status','start_status',
  'cancellation_status','withdrawal_scenario','withdrawal_possible','switch_can_be_stopped',
  'cancellation_required','billing_blocked','billing_manual_review','lifecycle_blocked',
  'start_date','end_date','actual_start_date','actual_end_date','starts_at','ends_at',
  'ended_at','signed_at','termination_notice_date','withdrawal_requested_at',
  'requested_start_date','confirmed_start_date','completed_at','failed_at',
  'submitted_at','resolved_at','closed_at','move_in_date','move_out_date',
  'happened_at','occurred_at','created_at','updated_at','archived_at','source_type','operation_id',
  'idempotency_key','actual_start_at','delivery_start_at','withdrawal_deadline_at'
 ];
BEGIN IF TG_OP='UPDATE' AND public.ediel_capture_customer_record_retention_origin_v1(TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW)) THEN RETURN NEW;END IF;
 IF TG_TABLE_SCHEMA<>'public' OR NOT EXISTS
  (SELECT FROM gridex_correction_process.epochs e WHERE e.table_name=TG_TABLE_NAME) THEN
  RAISE EXCEPTION 'correction_process_unregistered_producer' USING ERRCODE='23514';
 END IF;
 IF TG_OP<>'INSERT' THEN old_row:=to_jsonb(OLD); END IF;
 IF TG_OP<>'DELETE' THEN new_row:=to_jsonb(NEW); END IF;
 IF coalesce(octet_length(old_row::text),0)+coalesce(octet_length(new_row::text),0)>6291456 THEN
  RAISE EXCEPTION 'correction_process_transition_too_large' USING ERRCODE='22001';
 END IF;
 SELECT jsonb_object_agg(key,value) INTO old_fact FROM jsonb_each(old_row) WHERE key=ANY(fields);
 SELECT jsonb_object_agg(key,value) INTO new_fact FROM jsonb_each(new_row) WHERE key=ANY(fields);
 IF coalesce(octet_length(old_fact::text),0)>65536 OR coalesce(octet_length(new_fact::text),0)>65536 THEN
  RAISE EXCEPTION 'correction_process_fact_too_large' USING ERRCODE='22001';
 END IF;
 old_company:=old_row->>'company_id'; new_company:=new_row->>'company_id';
 selected_company:=coalesce(old_company,new_company)::uuid;
 INSERT INTO gridex_correction_process.facts(table_name,row_id,operation,company_id,old_fact,new_fact,facts_hash)
 VALUES (TG_TABLE_NAME,(coalesce(old_row,new_row)->>'id')::uuid,TG_OP,selected_company,old_fact,new_fact,
  encode(sha256(convert_to(jsonb_build_object('table',TG_TABLE_NAME,'rowId',coalesce(old_row,new_row)->>'id',
   'operation',TG_OP,'old',old_fact,'new',new_fact)::text,'UTF8')),'hex')) RETURNING id INTO fact_id;
 IF selected_company IS NULL OR (TG_OP='UPDATE' AND old_company IS DISTINCT FROM new_company) THEN
  INSERT INTO gridex_correction_process.gaps(fact_id,reason,old_scope,new_scope)
  VALUES(fact_id,CASE WHEN old_company IS NULL OR new_company IS NULL THEN 'unbound_company' ELSE 'company_changed' END,
   old_fact,new_fact);
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.gridex_apply_contract_offer_standard_fees()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_offer public.contract_offers%rowtype;
begin
  if new.contract_offer_id is null or new.company_id is null then
    return new;
  end if;

  -- Customer-specific/manual pricing is intentional and must not be replaced
  -- by catalog values merely because the original offer reference is retained.
  if coalesce(new.source_type, '') in ('manual', 'manual_override') then
    return new;
  end if;

  select offer.*
    into v_offer
  from public.contract_offers offer
  where offer.id = new.contract_offer_id
    and offer.company_id = new.company_id;

  if not found then
    return new;
  end if;

  new.monthly_fee_sek := v_offer.monthly_fee_sek;
  new.invoice_fee_sek := v_offer.invoice_fee_sek;
  new.green_fee_mode := v_offer.green_fee_mode;
  new.green_fee_value := v_offer.green_fee_value;
  new.discount_value := v_offer.discount_value;
  new.discount_unit := v_offer.discount_unit;
  new.start_fee_sek := v_offer.start_fee_sek;
  new.admin_fee_sek := v_offer.admin_fee_sek;
  new.break_fee_sek := v_offer.break_fee_sek;
  new.vat_rate := v_offer.vat_rate;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_audit_critical_row_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
      declare
        v_old jsonb := case when TG_OP in ('UPDATE','DELETE') then to_jsonb(OLD) else null end;
        v_new jsonb := case when TG_OP in ('INSERT','UPDATE') then to_jsonb(NEW) else null end;
        v_company_id uuid := null;
        v_actor uuid := null;
        v_entity_id text := null;
      begin
        if TG_TABLE_NAME = 'audit_logs' then
          return coalesce(NEW, OLD);
        end if;

        v_company_id := nullif(coalesce(v_new ->> 'company_id', v_old ->> 'company_id'), '')::uuid;
        if v_company_id is null and TG_TABLE_NAME = 'companies' then
          v_company_id := nullif(coalesce(v_new ->> 'id', v_old ->> 'id'), '')::uuid;
        end if;

        v_actor := nullif(coalesce(
          v_new ->> 'updated_by',
          v_new ->> 'created_by',
          v_new ->> 'actor_user_id',
          v_new ->> 'invited_by',
          v_new ->> 'paused_by',
          v_old ->> 'updated_by',
          v_old ->> 'created_by',
          v_old ->> 'actor_user_id',
          v_old ->> 'invited_by',
          v_old ->> 'paused_by'
        ), '')::uuid;

        v_entity_id := coalesce(v_new ->> 'id', v_old ->> 'id');

        insert into public.audit_logs (
          company_id,
          actor_user_id,
          entity_type,
          entity_id,
          action,
          old_values,
          new_values,
          metadata
        ) values (
          v_company_id,
          v_actor,
          TG_TABLE_NAME,
          v_entity_id,
          lower(TG_TABLE_NAME || '_' || TG_OP),
          v_old,
          v_new,
          jsonb_build_object(
            'source', 'gridex_audit_critical_row_change',
            'operation', TG_OP,
            'table', TG_TABLE_NAME
          )
        );

        return coalesce(NEW, OLD);
      end;
      $function$

CREATE OR REPLACE FUNCTION public.gridex_customer_contracts_company_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  parent_company_id uuid;
begin
  if new.customer_id is not null and to_regclass('public.customers') is not null then
    select company_id into parent_company_id from public.customers where id = new.customer_id;
    perform public.gridex_assert_same_company(new.company_id, parent_company_id, TG_TABLE_NAME, 'customer_id');
  end if;

  if new.site_id is not null and to_regclass('public.customer_sites') is not null then
    select company_id into parent_company_id from public.customer_sites where id = new.site_id;
    perform public.gridex_assert_same_company(new.company_id, parent_company_id, TG_TABLE_NAME, 'site_id');
  end if;

  if new.customer_site_id is not null and to_regclass('public.customer_sites') is not null then
    select company_id into parent_company_id from public.customer_sites where id = new.customer_site_id;
    perform public.gridex_assert_same_company(new.company_id, parent_company_id, TG_TABLE_NAME, 'customer_site_id');
  end if;

  if new.metering_point_id is not null and to_regclass('public.metering_points') is not null then
    select company_id into parent_company_id from public.metering_points where id = new.metering_point_id;
    perform public.gridex_assert_same_company(new.company_id, parent_company_id, TG_TABLE_NAME, 'metering_point_id');
  end if;

  return new;
end;
$function$

